def pay(http, order):
    for attempt in range(2):
        try:
            return http.post("http://billing:8080/charge", json={"order_id": order.id, "cents": order.cents}, timeout=3)
        except TimeoutError:
            if attempt == 1:
                raise

@app.post("/charge")
